import SwiftUI

/// Preview the saved generated bytes before the user explicitly starts printing.
struct InvoiceGeneratedDocumentView: View {
    @Environment(\.dismiss) private var dismiss
    let document: InvoiceDocument
    let isAuthorized: () -> Bool

    var body: some View {
        NavigationStack {
            Group {
                if isAuthorized() {
                    PDFPreview(document: document)
                } else {
                    ContentUnavailableView("auth.unavailable", systemImage: "lock")
                }
            }
            .navigationTitle("documents.title")
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("documents.close") { dismiss() }
                }
                ToolbarItem(placement: .primaryAction) {
                    if isAuthorized() {
                        PrintDocumentButton(document: document, isAuthorized: isAuthorized)
                            .frame(minWidth: 100, minHeight: 44)
                    }
                }
            }
        }
        #if os(macOS)
        .frame(minWidth: 600, minHeight: 650)
        #endif
    }
}

struct InvoicePreviewModifier: ViewModifier {
    @Bindable var preview: InvoicePreviewViewModel

    /// Presents progress, the document, or the preparation error at the call site.
    func body(content: Content) -> some View {
        content
            #if os(iOS)
            .fullScreenCover(item: $preview.document, onDismiss: { preview.cancel() }) { document in
                InvoiceGeneratedDocumentView(document: document, isAuthorized: { preview.isAvailable })
            }
            #else
            .sheet(item: $preview.document, onDismiss: { preview.cancel() }) { document in
                InvoiceGeneratedDocumentView(document: document, isAuthorized: { preview.isAvailable })
            }
            #endif
            .overlay {
                if preview.isGenerating {
                    ProgressView()
                        .padding()
                        .background(.regularMaterial, in: .capsule)
                }
            }
            .alert("documents.localPrintError", isPresented: $preview.failed) {
                Button("documents.close", role: .cancel) { }
            }
    }
}
